INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-02-24-france-ppf-pilot-opens', '2026-02-24', '2026-02', 'France''s PPF pilot phase opens for voluntary testing ahead of the September 2026 e-invoicing mandate, with a participation window running through the end of August.', '<h3>🇫🇷 France opens voluntary PPF pilot ahead of September mandate</h3>
<p>Businesses can now register to voluntarily test France''s e-invoicing and e-reporting flows ahead of the mandatory 1 September 2026 go-live, in a pilot window running from the end of February through the end of August. Participation is open to any VAT-registered business willing to route real invoices through a Plateforme Agréée (PA) on a live basis, rather than waiting to find out how their setup performs only once the legal obligation actually begins.</p>
<p>The pilot opens against a backdrop of real infrastructure progress: AFNOR''s technical specifications and API standard have been finalised, the DGFiP has formally taken on the role of France''s Peppol authority, and — as of this point in the rollout — over 100 Plateformes Agréées have already received DGFiP accreditation, giving businesses a genuine, functioning choice of certified provider well ahead of the deadline rather than a scramble at the last minute.</p>
<p><strong>What this means for your team:</strong> if your business will need to issue e-invoices from day one — large enterprises and mid-sized companies (ETIs) are first in scope — earlier pilot participation buys real time to find and fix integration problems while there''s no penalty for getting it wrong. Waiting until closer to September means testing a live, mandatory system for the first time with no room left to course-correct.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/france.html" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full France Deep Dive for complete technical detail →</a></p>', 'https://www.impots.gouv.fr/actualite/facturation-electronique-publication-de-la-liste-des-plateformes-agreees', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-02-24-france-ppf-pilot-opens', id FROM countries WHERE name_en = 'France';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-02-24-france-ppf-pilot-opens', 'en', 'France opens voluntary PPF pilot ahead of September mandate', 'France''s PPF pilot phase opens for voluntary testing ahead of the September 2026 e-invoicing mandate, with a participation window running through the end of August.', '<h3>🇫🇷 France opens voluntary PPF pilot ahead of September mandate</h3>
<p>Businesses can now register to voluntarily test France''s e-invoicing and e-reporting flows ahead of the mandatory 1 September 2026 go-live, in a pilot window running from the end of February through the end of August. Participation is open to any VAT-registered business willing to route real invoices through a Plateforme Agréée (PA) on a live basis, rather than waiting to find out how their setup performs only once the legal obligation actually begins.</p>
<p>The pilot opens against a backdrop of real infrastructure progress: AFNOR''s technical specifications and API standard have been finalised, the DGFiP has formally taken on the role of France''s Peppol authority, and — as of this point in the rollout — over 100 Plateformes Agréées have already received DGFiP accreditation, giving businesses a genuine, functioning choice of certified provider well ahead of the deadline rather than a scramble at the last minute.</p>
<p><strong>What this means for your team:</strong> if your business will need to issue e-invoices from day one — large enterprises and mid-sized companies (ETIs) are first in scope — earlier pilot participation buys real time to find and fix integration problems while there''s no penalty for getting it wrong. Waiting until closer to September means testing a live, mandatory system for the first time with no room left to course-correct.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/france.html" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full France Deep Dive for complete technical detail →</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-10-france-no-delay-confirmed', '2026-07-10', '2026-07', 'DGFiP has confirmed France''s e-invoicing mandate proceeds on 1 September 2026 without postponement, despite market speculation, while pairing this with a pragmatic ''soft-landing'' approach to enforcement for good-faith businesses.', '<h3>🇫🇷 DGFiP confirms no delay to the 1 September mandate — but softens enforcement</h3>
<p>At a 10 July meeting with industry stakeholders, the DGFiP formally recommitted to the 1 September 2026 start date, closing off weeks of market speculation that the mandate might slip to 1 December — a deferral the underlying legislation technically permits, but which the tax authority has now explicitly ruled out. Amélie Verdier, Director General of the DGFiP, acknowledged directly that not every business will be ready in time, stating there would be "no automatic and blind sanctions" once the mandate takes effect.</p>
<p>That distinction matters: the legal deadline itself is not moving, only the posture around enforcing it. Invoices received by PDF, email, or paper after 1 September will remain valid, payable, and VAT-deductible for businesses that can show genuine, documented difficulty and active progress toward compliance — this is not a blanket grace period, and the DGFiP has published a practical 29-question guide setting out exactly what "actively progressing" is expected to look like in practice, rather than leaving it to interpretation.</p>
<p><strong>What this means for your team:</strong> don''t mistake a softer enforcement posture for a moved deadline. The obligation to receive e-invoices from 1 September applies to every in-scope business regardless of readiness, and large/mid-sized companies must also issue and e-report from that date. If you expect to rely on any fallback arrangement, treat it as a genuinely temporary bridge you''re actively closing — not a workaround to settle into — since the DGFiP''s own guidance is explicit that ongoing, demonstrable progress is the condition for any leniency at all.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/france.html" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full France Deep Dive for complete technical detail →</a></p>', 'https://www.impots.gouv.fr/facturation-electronique-et-plateformes-agreees', 1);
