INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-10-france-no-delay-confirmed', 'en', 'DGFiP confirms no delay to the 1 September mandate — but softens enforcement', 'DGFiP has confirmed France''s e-invoicing mandate proceeds on 1 September 2026 without postponement, despite market speculation, while pairing this with a pragmatic ''soft-landing'' approach to enforcement for good-faith businesses.', '<h3>🇫🇷 DGFiP confirms no delay to the 1 September mandate — but softens enforcement</h3>
<p>At a 10 July meeting with industry stakeholders, the DGFiP formally recommitted to the 1 September 2026 start date, closing off weeks of market speculation that the mandate might slip to 1 December — a deferral the underlying legislation technically permits, but which the tax authority has now explicitly ruled out. Amélie Verdier, Director General of the DGFiP, acknowledged directly that not every business will be ready in time, stating there would be "no automatic and blind sanctions" once the mandate takes effect.</p>
<p>That distinction matters: the legal deadline itself is not moving, only the posture around enforcing it. Invoices received by PDF, email, or paper after 1 September will remain valid, payable, and VAT-deductible for businesses that can show genuine, documented difficulty and active progress toward compliance — this is not a blanket grace period, and the DGFiP has published a practical 29-question guide setting out exactly what "actively progressing" is expected to look like in practice, rather than leaving it to interpretation.</p>
<p><strong>What this means for your team:</strong> don''t mistake a softer enforcement posture for a moved deadline. The obligation to receive e-invoices from 1 September applies to every in-scope business regardless of readiness, and large/mid-sized companies must also issue and e-report from that date. If you expect to rely on any fallback arrangement, treat it as a genuinely temporary bridge you''re actively closing — not a workaround to settle into — since the DGFiP''s own guidance is explicit that ongoing, demonstrable progress is the condition for any leniency at all.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/france.html" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full France Deep Dive for complete technical detail →</a></p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-28-france-readiness-numbers', '2026-07-28', '2026-07', 'With roughly 50 days until go-live, fresh DGFiP/AIFE pilot statistics show only a small fraction of France''s eventual 11 million in-scope businesses have actually tested the system so far.', '<h3>🇫🇷 France''s e-invoicing readiness numbers, with 50 days to go</h3>
<p>The DGFiP and AIFE, who have run the PPF pilot since February, have shared fresh platform and onboarding figures, and they paint a sobering picture of how much ground is left to cover. Of close to 150 Plateformes Agréées now registered, only around 25 are currently active in actually transmitting data through the system — the rest are accredited but not yet genuinely moving live invoices.</p>
<p>Company-side participation looks thinner still: just 3,800 entities have issued e-invoices and 3,400 have received them through the pilot to date, against a total of more than 11 million entities eventually in scope — a participation rate of roughly 0.025%. Most strikingly, among the exact group facing an immediate issuance obligation from 1 September — large enterprises and mid-sized companies (ETIs) — only 9 Large companies and 37 Mid-sized companies have issued a single invoice through the pilot so far.</p>
<p><strong>What this means for your team:</strong> if you''re a Large or ETI business with an issuance obligation from day one, these figures are a useful reality check — the overwhelming majority of your peer group hasn''t validated their own flow yet either, so don''t assume the wider market is quietly ahead of where you are. Combined with the fact that some technical guidelines and legislative texts are still pending finalisation ahead of a public consultation window, this is genuinely not the moment to treat pilot testing as optional or routine.</p>
<p style="margin-top:18px; padding-top:14px; border-top:1px dashed #c9bd9e;"><a href="https://e-invoicingcompliancecorner.com/france.html" style="color:#b5432f; text-decoration:underline; font-weight:600; font-size:13px;">📖 Read the full France Deep Dive for complete technical detail →</a></p>', 'https://www.impots.gouv.fr/professionnel/je-passe-la-facturation-electronique', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-07-28-france-readiness-numbers', id FROM countries WHERE name_en = 'France';
